// 1. Input Validation & Fault Latching
if (ep_input.enable != 1 && ep_input.enable != 0) {
    ep_output.mode = EP_FAULT;
    ep_output.elapsed = 0;
    ep_output.payload_on = 0;
    ep_output.heater_on = 0;
    ep_output.axial_m = 0.0;
    ep_output.cross_track_m = 0.0;
    return;
}

int valid_enable = (ep_input.enable == 1);

if (ep_input.position_eci_m == NULL || ep_input.sun_direction_eci == NULL) {
    ep_output.mode = EP_FAULT;
    ep_output.elapsed = 0;
    ep_output.payload_on = 0;
    ep_output.heater_on = 0;
    ep_output.axial_m = 0.0;
    ep_output.cross_track_m = 0.0;
    return;
}

if (!adcs_is_finite_vec3(ep_input.position_eci_m) || !adcs_is_finite_vec3(ep_input.sun_direction_eci)) {
    ep_output.mode = EP_FAULT;
    ep_output.elapsed = 0;
    ep_output.payload_on = 0;
    ep_output.heater_on = 0;
    ep_output.axial_m = 0.0;
    ep_output.cross_track_m = 0.0;
    return;
}

if (!isfinite(ep_config.earth_radius_m) || ep_config.earth_radius_m <= 0.0) {
    ep_output.mode = EP_FAULT;
    ep_output.elapsed = 0;
    ep_output.payload_on = 0;
    ep_output.heater_on = 0;
    ep_output.axial_m = 0.0;
    ep_output.cross_track_m = 0.0;
    return;
}

if (ep_config.recovery_cycles < 1 || ep_config.recovery_cycles > 100 ||
    ep_config.warmup_cycles < 1 || ep_config.warmup_cycles > 100) {
    ep_output.mode = EP_FAULT;
    ep_output.elapsed = 0;
    ep_output.payload_on = 0;
    ep_output.heater_on = 0;
    ep_output.axial_m = 0.0;
    ep_output.cross_track_m = 0.0;
    return;
}

if (!isfinite(ep_input.battery_soc) || ep_input.battery_soc < 0.0 || ep_input.battery_soc > 1.0 ||
    !isfinite(ep_config.payload_on_soc) || ep_config.payload_on_soc < 0.0 || ep_config.payload_on_soc > 1.0 ||
    !isfinite(ep_config.payload_off_soc) || ep_config.payload_off_soc < 0.0 || ep_config.payload_off_soc > 1.0 ||
    ep_config.payload_off_soc > ep_config.payload_on_soc) {
    ep_output.mode = EP_FAULT;
    ep_output.elapsed = 0;
    ep_output.payload_on = 0;
    ep_output.heater_on = 0;
    ep_output.axial_m = 0.0;
    ep_output.cross_track_m = 0.0;
    return;
}

// 2. Disabled State Handling
if (!valid_enable) {
    ep_output.mode = EP_SUN;
    ep_output.elapsed = 0;
    ep_output.payload_on = 0;
    ep_output.heater_on = 0;

    adcs_vec3_t unit_sun;
    if (adcs_vec3_normalize(ep_input.sun_direction_eci, ADCS_EPS_NORM, &unit_sun) != ADCS_OK) {
        ep_output.mode = EP_FAULT;
        ep_output.elapsed = 0;
        ep_output.payload_on = 0;
        ep_output.heater_on = 0;
        ep_output.axial_m = 0.0;
        ep_output.cross_track_m = 0.0;
        return;
    }

    double axial_proj = adcs_vec3_dot(ep_input.position_eci_m, &unit_sun);
    adcs_vec3_t proj_vec = adcs_vec3_scale(&unit_sun, axial_proj);
    adcs_vec3_t perp_vec = adcs_vec3_sub(ep_input.position_eci_m, &proj_vec);
    ep_output.axial_m = axial_proj;
    ep_output.cross_track_m = adcs_vec3_norm(&perp_vec);
    return;
}

// 3. Eclipse Detection Calculation
adcs_vec3_t unit_sun;
if (adcs_vec3_normalize(ep_input.sun_direction_eci, ADCS_EPS_NORM, &unit_sun) != ADCS_OK) {
    ep_output.mode = EP_FAULT;
    ep_output.elapsed = 0;
    ep_output.payload_on = 0;
    ep_output.heater_on = 0;
    ep_output.axial_m = 0.0;
    ep_output.cross_track_m = 0.0;
    return;
}

double axial_m = adcs_vec3_dot(ep_input.position_eci_m, &unit_sun);
adcs_vec3_t proj_vec = adcs_vec3_scale(&unit_sun, axial_m);
adcs_vec3_t perp_vec = adcs_vec3_sub(ep_input.position_eci_m, &proj_vec);
double cross_track_m = adcs_vec3_norm(&perp_vec);

ep_output.axial_m = axial_m;
ep_output.cross_track_m = cross_track_m;

// 4. Eclipse Logic
if (axial_m < 0.0 && cross_track_m < ep_config.earth_radius_m) {
    ep_output.mode = EP_ECLIPSE;
    ep_output.elapsed = 0;
    ep_output.payload_on = 0;
    ep_output.heater_on = 1;
    ep_state.mode = EP_ECLIPSE;
    ep_state.elapsed = 0;
    return;
}

// 5. Sunlight Logic
ep_mode_t next_mode = ep_state.mode;
unint32 next_elapsed = 0;
int payload_on = 0;
int heater_on = 0;

if (ep_state.mode == EP_ECLIPSE) {
    next_mode = EP_RECOVERY;
    next_elapsed = 1;
} else if (ep_state.mode == EP_RECOVERY) {
    next_elapsed = ep_state.elapsed + 1;
    if (next_elapsed >= ep_config.recovery_cycles) {
        next_mode = EP_WARMUP;
        next_elapsed = 1;
    }
} else if (ep_state.mode == EP_WARMUP) {
    next_elapsed = ep_state.elapsed + 1;
    if (next_elapsed >= ep_config.warmup_cycles) {
        if (ep_input.battery_soc >= ep_config.payload_on_soc) {
            next_mode = EP_SUN;
            next_elapsed = 0;
        } else {
            next_mode = EP_LOADWAIT;
            next_elapsed = 0;
        }
    }
} else if (ep_state.mode == EP_LOADWAIT) {
    next_elapsed = ep_state.elapsed + 1;
    if (ep_input.battery_soc >= ep_config.payload_on_soc) {
        next_mode = EP_SUN;
        next_elapsed = 0;
    }
} else if (ep_state.mode == EP_SUN) {
    next_elapsed = ep_state.elapsed + 1;
    payload_on = 1;
    heater_on = 0;

    if (ep_input.battery_soc < ep_config.payload_off_soc) {
        next_mode = EP_LOADSHED;
        next_elapsed = 0;
        payload_on = 0;
    }
} else if (ep_state.mode == EP_LOADSHED) {
    next_elapsed = ep_state.elapsed + 1;
    payload_on = 0;
    heater_on = 0;

    if (ep_input.battery_soc >= ep_config.payload_on_soc) {
        next_mode = EP_SUN;
        next_elapsed = 0;
    }
}

ep_state.mode = next_mode;
ep_state.elapsed = next_elapsed;

ep_output.mode = next_mode;
ep_output.elapsed = next_elapsed;
ep_output.payload_on = payload_on;
ep_output.heater_on = heater_on;

